			click.pan(map(b.pos.x, -height / 2, height / 2, -1, 1))
			b.state = 1 - b.state;
			switch (b.type) {
				case 'top':
					if (b.state == 1) {
						if (i % 2 == 0) beads[i + 1].state = b.state;
					} else {
						if (i % 2 == 1) beads[i - 1].state = b.state;
					}
					break;
				case 'bottom':
					if (b.state == 1) {
						for (let j = 1; j < 5 - b.val; j++) {
							beads[i + j].state = b.state;
						}
						break;
					} else {
						for (let j = 1; j < b.val + 1; j++) {
							beads[i - j].state = b.state;
						}
						break;
					}
					break;
			}
		}
	}
	let newnum = calculateValue();
	display.html(newnum);
	slider.value(newnum);
}

function playClick() {
	click.play();
}

function calculateValue() {
	let num = 0;
	let add = 0;
	for (let b of beads) {
		num += b.pow * b.state * Math.pow(10, b.place);
	}
	return nf(num, 9);
}

function updateBeads() {
	let newval = slider.value();
	let digits = [];
	for (let i = 0; i < 10; i++) {
		let d = floor(newval / Math.pow(10, i)) % 10;
		digits.push(d);
	}
	for (let i = 0; i < digits.length; i++) {
		for (let b of beads) {
			if (b.place == i) {
				if (digits[i] != 0) {
					b.state = 0;
					if (digits[i] > 4 && b.val == 1 && b.type == 'top') b.state = 1;
					if (digits[i] % 5 > 4 - b.val && b.type == 'bottom') b.state = 1;
				} else {
					b.state = 0;
				}
			}
		}
	}
	display.html(nf(newval, 9));
	setTimeout(playClick, 100);
}

